/**
 * FlowsPage takes a connection filter from the URL: FlowDetail's
 * "Flows on this connection" link opens `/?conn_id=<id>`, and the page must
 * send that value verbatim as `filter.conn_id` to `query resource=flows`.
 *
 * The data hooks are mocked so every `useQuery` call is recorded, and the
 * page is rendered with renderToStaticMarkup (no jsdom / RTL — see
 * hooks.test.ts header). flows-same-conn.response.json is a real
 * `query resource=flows filter:{conn_id}` response for two h2 streams
 * multiplexed on one client connection, generated by
 * internal/mcp/webui_http_fixture_test.go.
 */

import { createElement } from "react";
import { renderToStaticMarkup } from "react-dom/server";
import { MemoryRouter, Route, Routes } from "react-router-dom";
import { beforeEach, describe, expect, it, vi } from "vitest";
import type { FlowsResult } from "../../lib/mcp/types.js";
import sameConnText from "./__fixtures__/flows-same-conn.response.json?raw";

interface RecordedQuery {
  resource: string;
  options: { filter?: Record<string, unknown> } & Record<string, unknown>;
}

const mockState = vi.hoisted(() => ({
  flows: null as unknown,
  calls: [] as RecordedQuery[],
}));

vi.mock("../../lib/mcp/hooks.js", () => ({
  useQuery: (resource: string, options: RecordedQuery["options"] = {}) => {
    mockState.calls.push({ resource, options });
    return {
      data: resource === "flows" ? mockState.flows : null,
      loading: false,
      error: null,
      refetch: () => {},
    };
  },
  useManage: () => ({ manage: async () => ({}), loading: false }),
}));

vi.mock("../../components/ui/toastContext.js", () => ({
  useToast: () => ({ addToast: () => {} }),
}));

vi.mock("../../components/ui/dialogContext.js", () => ({
  useDialog: () => ({ showDialog: async () => false }),
}));

// Import after the mocks are registered so the page resolves the stubs.
const { FlowsPage } = await import("./FlowsPage.js");

const sameConn = JSON.parse(sameConnText) as FlowsResult;
const sharedConn = "conn-h2-multiplexed";

function render(url: string): { html: string; query: RecordedQuery } {
  const html = renderToStaticMarkup(
    createElement(
      MemoryRouter,
      { initialEntries: [url] },
      createElement(
        Routes,
        null,
        createElement(Route, { index: true, element: createElement(FlowsPage) }),
      ),
    ),
  );
  const flows = mockState.calls.filter((c) => c.resource === "flows");
  // Guard against a vacuous pass if the page stops calling the hook.
  expect(flows).toHaveLength(1);
  return { html, query: flows[0] };
}

/** Text of every ID cell in the flows table. */
function idCells(html: string): string[] {
  return [...html.matchAll(/<td class="flows-cell-id">([^<]*)<\/td>/g)].map((m) => m[1]);
}

beforeEach(() => {
  mockState.flows = null;
  mockState.calls = [];
});

describe("FlowsPage conn_id URL filter", () => {
  it("sends the conn_id URL parameter as filter.conn_id", () => {
    const { query } = render(`/?${new URLSearchParams({ conn_id: sharedConn })}`);
    expect(query.options.filter).toEqual({ conn_id: sharedConn });
  });

  it("sends the conn_id verbatim, without trimming or case folding", () => {
    const { query } = render(`/?${new URLSearchParams({ conn_id: " Conn A&b " })}`);
    expect(query.options.filter).toEqual({ conn_id: " Conn A&b " });
  });

  it("sends no conn_id filter without the URL parameter", () => {
    const { query } = render("/");
    expect(query.options.filter).toBeUndefined();
  });

  it("shows the active connection filter outside the collapsed filters panel", () => {
    const { html } = render(`/?${new URLSearchParams({ conn_id: sharedConn })}`);
    expect(html).toContain("flows-active-filter");
    expect(html).toContain(`Connection: ${sharedConn}`);
    // The filters panel starts collapsed, so the chip is not inside it.
    expect(html).not.toContain("flows-filters\"");
  });

  it("shows no connection chip without the URL parameter", () => {
    const { html } = render("/");
    expect(html).not.toContain("flows-active-filter");
    expect(html).not.toContain("Connection:");
  });

  it("lists every h2 stream of the connection from the real filtered response", () => {
    expect(sameConn.total).toBe(2);
    mockState.flows = sameConn;
    const { html, query } = render(`/?${new URLSearchParams({ conn_id: sharedConn })}`);
    expect(query.options.filter).toEqual({ conn_id: sharedConn });
    // The ID cell shows the first 8 characters; the fixture's stream IDs
    // differ there, so both rows are distinguishable.
    expect(idCells(html)).toEqual(
      sameConn.flows.map((f) => f.id.slice(0, 8)),
    );
    expect(idCells(html)).toEqual(["s1-samec", "s3-samec"]);
  });

  it("says no flows are on the connection when the filtered list is empty", () => {
    mockState.flows = { flows: [], count: 0, total: 0 };
    const { html } = render(`/?${new URLSearchParams({ conn_id: sharedConn })}`);
    expect(html).toContain("No flows on this connection");
  });
});
